examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchDeltaIndicator(value = {{items.0.value}}, comparison = {{items.0.comparison}})
        MonarchDeltaIndicator(value = {{items.1.value}}, comparison = {{items.1.comparison}})
        MonarchDeltaIndicator(
            value = ({{items.2.current}} - {{items.2.previous}}).toDouble(),
            comparison = {{items.2.comparison}},
            goodDirection = MonarchDeltaIndicatorGoodDirection.{{items.2.goodDirection|pascal}},
                        formatValue = { "${kotlin.math.abs(it).toInt()} {{items.2.unit|raw}}" },
        )
        MonarchDeltaIndicator(
            value = {{items.3.value}}.0,
            comparison = {{items.3.comparison}},
            goodDirection = MonarchDeltaIndicatorGoodDirection.{{items.3.goodDirection|pascal}},
                        formatValue = { NumberFormat.getCurrencyInstance(locale.locales[0]).apply { currency = Currency.getInstance({{items.3.currency}}) }.format(it) },
        )
    }
}

examples.setupTemplate:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

examples.setup:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-US")) }
}

examples.code:
CompositionLocalProvider(LocalConfiguration provides locale) {
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchDeltaIndicator(value = 0.124, comparison = "vs last month")
        MonarchDeltaIndicator(value = -0.052, comparison = "vs last month")
        MonarchDeltaIndicator(
            value = (182 - 240).toDouble(),
            comparison = "vs last week",
            goodDirection = MonarchDeltaIndicatorGoodDirection.Down,
                        formatValue = { "${kotlin.math.abs(it).toInt()} ms" },
        )
        MonarchDeltaIndicator(
            value = 1250.0,
            comparison = "in spend",
            goodDirection = MonarchDeltaIndicatorGoodDirection.Down,
                        formatValue = { NumberFormat.getCurrencyInstance(locale.locales[0]).apply { currency = Currency.getInstance("USD") }.format(it) },
        )
    }
}
